  if (result.rowCount === 0) return null;
  const { rows } = await query(
    'SELECT * FROM mastery_goals WHERE id = $1 AND user_id = $2 LIMIT 1',
    [goalId, userId]
  );
  return rows[0] ? _normalizeMasteryGoalRow({ id: goalId, ...rows[0] }) : null;
