const todayStr = Number.isFinite(requestedTime) && Math.abs(requestedTime - Date.now()) <= 36 * 3600000
? requestedDate
: serverToday;
const safeTimezoneOffset = Math.max(-840, Math.min(840, Number(timezoneOffsetMinutes) || 0));
